INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-bd7-rhino-bulldozer', 1, 'Defensive Ion Gun', '4D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear or Solid Oxide models; 60 blasts on electric battery or liquid fuel models. Its E-Clip port gives 10 blasts from a short E-Clip, 20 from a long one.', NULL, 'Ring-mounted turret on the cab, firing through 360 degrees with a 25 degree up and down arc; worked from inside, so the driver need not open a hatch. Defense and anti-personnel.'),
  ('ng-bd7-rhino-bulldozer', 2, 'Bulldozer Attacks', 'Slow precision push against a wall, fence or door 2D6 M.D.; blade drop 3D6 M.D.; low-speed ram 4D6 M.D. (two attacks); high-speed ram at 30 mph (48 km) or more 1D4x10 M.D. (three attacks)', 1, NULL, NULL, NULL, NULL, 'The high-speed ram has a 01-66% chance to knock down power armor and robots of up to 12 tons, which then lose initiative and a melee attack. Driven into a crowd or a line of people it does 2D6 M.D. to each, and everyone in its path is shoved aside, losing initiative and 1D6 melee attacks.'),
  ('ng-f911-smokeskipper', 1, 'Main Water Cannon', '2D4x10 Hit Points to vampires with a 01-40% chance of knockdown; ordinary humans take 1D6 S.D.C./Hit Points with a 01-75% chance of being knocked down (losing initiative and one melee attack)', 0, '1,200 ft (365 m)', 'Each blast uses one of the gunner''s melee attacks', '40 streams from the internal tank; effectively unlimited hooked to a water source', NULL, 'Central roof turret turning 360 degrees, elevating or depressing 45 degrees. Firefighting and rescue; anti-vampire.'),
  ('ng-f911-smokeskipper', 2, 'Secondary Water Cannons (3)', '5D6 Hit Points to vampires with a 01-10% chance of knockdown', 0, '600 ft (183 m)', 'Each blast uses one of its operator''s attacks', '80 streams from the internal tank; effectively unlimited hooked to a water source', NULL, 'Two in rear turrets and one on the cherry-picker. Firefighting; anti-vampire.'),
  ('ng-f911-smokeskipper', 3, 'Mini-Missile Launcher', 'Firefighting chemical missiles do no damage but smother fire in a 30 ft (9.1 m) radius; combat mini-missiles by type; fragmentation missiles salted with silver do 3D6 Hit Points to every vampire (and unarmored bystander) within a 10 ft (3 m) radius', 1, '2,000 ft (610 m) for chemical missiles; one mile for combat mini-missiles (the page prints 1.6 m)', 'One at a time or in volleys of 2, 4 or 6', '12 mini-missiles', NULL, 'Hidden behind a sliding panel beside the driver; usually loaded with fire-retardant missiles but takes any mini-missile. Firefighting; riot control and self-defense.'),
  ('ng-hc28-urban-patrol-hovercar', 1, 'Pursuit Laser', '2D6 M.D. per shot', 1, '2,000 ft (610 m)', 'Each blast counts as one melee action/attack', 'Effectively unlimited on nuclear and Solid Oxide; 90 blasts per electric battery charge', NULL, 'A light laser set in front of the passenger seat, for stopping fleeing vehicles and armoured criminals. Defense; anti-personnel.'),
  ('ng-hc28-urban-patrol-hovercar', 2, 'NG-GL10A Grenade Launcher', 'By grenade: fragmentation 3D6 M.D. to a 12 ft (3.7 m) radius; high explosive/armor piercing 4D6 M.D. to a 3 ft (0.9 m) radius; plasma 6D6 M.D. to a 5 ft (1.5 m) radius; smoke fills a 40 ft (12.2 m) radius; tear gas covers a 25 ft (7.6 m) radius; stun/flash', 1, '1,000 ft (305 m)', 'Single shot; each counts as one melee attack', '40 round drum', NULL, 'Roof mount worked through the hatch/sunroof. Tear gas leaves anyone without a gas mask or environmental armor -10 to strike, parry and dodge, -3 on initiative and down one melee attack for as long as they stay in the cloud plus 1D6+1 melee rounds. Stun/flash costs victims one melee attack and gives -1 on initiative and -10 to strike, parry and dodge, for 1D4 melee rounds. Anti-personnel and riot control; defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 machines are in' AS assertion, count(*) AS got, 6 AS want
  FROM vehicles WHERE slug IN ('ng-bd7-rhino-bulldozer', 'ng-road-king-armored-suv', 'ng-hch-1020-salamander', 'ng-f911-smokeskipper', 'ng-hc28-urban-patrol-hovercar', 'ng-epc-18-wolftrack');
SELECT 'their 64 locations are in' AS assertion, count(*) AS got, 64 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-bd7-rhino-bulldozer', 'ng-road-king-armored-suv', 'ng-hch-1020-salamander', 'ng-f911-smokeskipper', 'ng-hc28-urban-patrol-hovercar', 'ng-epc-18-wolftrack');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-bd7-rhino-bulldozer', 'ng-road-king-armored-suv', 'ng-hch-1020-salamander', 'ng-f911-smokeskipper', 'ng-hc28-urban-patrol-hovercar', 'ng-epc-18-wolftrack');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-bd7-rhino-bulldozer', 'ng-road-king-armored-suv', 'ng-hch-1020-salamander', 'ng-f911-smokeskipper', 'ng-hc28-urban-patrol-hovercar', 'ng-epc-18-wolftrack') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

